function getCategory(type,pid){
  if(pid==="email")return "EMAIL";
  if(pid==="website")return "WEBSITE";
  const t=(type||"").toLowerCase();
  if(["storytelling","challenge","documentary","mystery","experiment","comparison"].some(k=>t.startsWith(k)))return "VIDEO_LONG";
  if(["reels","فيديو hook","fail","wait","curiosity","animals","social exp","relatable","trend","short story","shorts"].some(k=>t.startsWith(k)))return "VIDEO_SHORT";
  if(["carousel","infographic","tips","قائمة","before","قبل","ugc"].some(k=>t.startsWith(k)))return "DESIGN";
  if(["stories","كواليس","لقطات"].some(k=>t.startsWith(k)))return "STORY";
  if(["pdf","تقرير","رابط فيديو","صوتية","تنبيه"].some(k=>t.startsWith(k)))return "MSG";
  return "TEXT";
}
function getDefTasks(cat,st){return((DEFAULT_TASKS[cat]||DEFAULT_TASKS.TEXT)[st]||[]).map((text,i)=>({id:"d_"+i,text,isDefault:true}));}
function getDefFields(cat,st){return(DEFAULT_FIELDS[cat]||DEFAULT_FIELDS.TEXT)[st]||[];}
function getEffectiveTasks(post,cat,st){const o=(post.taskOverrides||{})[st];return o||getDefTasks(cat,st);}
function getEffectiveFields(post,cat,st){const o=(post.fieldOverrides||{})[st];return o||getDefFields(cat,st);}
function getTypeName(plan,pid,type){
  if(!type)return "";
  const list=getContentTypes(plan,pid)||[];
  const found=list.find(t=>(t.id||t)===type);
  return found?(found.name||found):type;
}
function formatTime(t){
  if(!t||typeof t!=="object")return t||"";
  const mm=String(t.m).padStart(2,"0");
  if(t.use24)return `${String(t.h).padStart(2,"0")}:${mm}`;
  return `${t.h}:${mm} ${t.period==="AM"?"صباحاً":"مساءً"}`;
}
function postsNext7Days(plan,todayKey){
  const t=new Date(todayKey+"T12:00:00"); const end=new Date(t); end.setDate(end.getDate()+7);
  const endK=`${end.getFullYear()}-${String(end.getMonth()+1).padStart(2,"0")}-${String(end.getDate()).padStart(2,"0")}`;
  return getAllPosts(plan).filter(p=>p.dateKey>=todayKey&&p.dateKey<=endK).sort((a,b)=>a.dateKey.localeCompare(b.dateKey)||String(a.id||"").localeCompare(String(b.id||""))).slice(0,24);
}

function getAllPosts(plan){
  if(!plan || typeof plan!=="object") return [];
  const out=[];
  const dateKeyRe=/^\d{4}-\d{2}-\d{2}$/;
  Object.keys(plan).forEach(key=>{
    if(!dateKeyRe.test(key)) return;
    const bucket=plan[key];
    if(!Array.isArray(bucket)) return;
    bucket.forEach((post,idx)=>{
      if(!post || typeof post!=="object") return;
      out.push({...post,dateKey:post.dateKey||key,_planDateKey:key,_planIndex:idx});
    });
  });
  return out;
}

function getLayerGroups(plan){ return (plan&&plan._layerGroups&&plan._layerGroups.length>0)?plan._layerGroups:DEFAULT_LAYER_GROUPS; }
function getLayers(plan){ return (plan&&plan._layers&&plan._layers.length>0)?plan._layers:DEFAULT_LAYERS; }
function getLayersByGroup(plan,gid){ return getLayers(plan).filter(l=>l.groupId===gid); }
function getLayerGroupById(plan,gid){ return getLayerGroups(plan).find(g=>g.id===gid)||null; }
function getLayerById(plan,id){ return getLayers(plan).find(l=>l.id===id)||null; }
function getPrimaryLayerGroup(plan){ const gs=getLayerGroups(plan).slice().sort((a,b)=>(a.order||0)-(b.order||0)); return gs[0]||null; }
// Normalizes a post's stored value for one layer group to an array of layer ids, regardless of
// whether it was saved as a single id (single-select groups) or an array (multi-select groups).
function getPostLayerIds(plan,post,groupId){
  const v=post&&post.layers&&post.layers[groupId];
  if(!v) return [];
  return Array.isArray(v)?v.filter(Boolean):[v];
}
function getPostLayer(plan,post,groupId){
  const gid=groupId||(getPrimaryLayerGroup(plan)||{}).id;
  if(!gid) return null;
  const ids=getPostLayerIds(plan,post,gid);
  return ids.length?getLayerById(plan,ids[0]):null;
}
function getPostLayerChips(plan,post){
  if(!post||!post.layers) return [];
  const groups=getLayerGroups(plan).slice().sort((a,b)=>(a.order||0)-(b.order||0));
  const out=[];
  groups.forEach(g=>{
    getPostLayerIds(plan,post,g.id).forEach(lid=>{
      const l=getLayerById(plan,lid); if(l) out.push({group:g,layer:l});
    });
  });
  return out;
}
