// ── CONTENT DNA ─────────────────────────────────────────────
// Structural/production metadata captured per post, independent of Layers
// (which classify *meaning*). DNA captures *form* — duration, visual/audio
// choices — so later the Insights Engine can correlate form with performance.
const DNA_FIELDS=[
  {k:"duration",         l:"المدة (ثانية)",        t:"number"},
  {k:"aspectRatio",      l:"نسبة العرض",            t:"select", opts:["9:16","1:1","16:9","4:5"]},
  {k:"hasFace",          l:"يظهر وجه",              t:"bool"},
  {k:"hasSubtitle",      l:"ترجمة/Subtitle",         t:"bool"},
  {k:"hasCaption",       l:"نص على الشاشة",          t:"bool"},
  {k:"musicType",        l:"الموسيقى",               t:"select", opts:["Trending","Original","None"]},
  {k:"firstSeconds",     l:"قوة أول 3 ثوانٍ",        t:"select", opts:["Weak","Medium","Strong"]},
  {k:"storytelling",     l:"Storytelling",           t:"bool"},
  {k:"patternInterrupt", l:"Pattern Interrupt",      t:"bool"},
  {k:"aiVoice",          l:"صوت AI",                 t:"bool"},
];
function getDnaFieldLabel(k,v){
  const f=DNA_FIELDS.find(x=>x.k===k); if(!f) return String(v);
  if(f.t==="bool") return v?f.l:null;
  return v!=null&&v!==""?`${f.l}: ${v}`:null;
}

