  const y=d.getFullYear(), m=d.getMonth();
  const last=new Date(y,m+1,0).getDate();
  for(let i=1;i<=last;i++) keys.push(`${y}-${String(m+1).padStart(2,"0")}-${String(i).padStart(2,"0")}`);
