function logAction(plan, user, type, desc, targetId=null, currentPage="") {
  const history = plan._history || [];
  const entry = {
    id: "hist_" + Date.now() + "_" + Math.random().toString(36).slice(2, 5),
    ts: Date.now(),
    userId: user?.id || "system",
    userName: user?.name || "النظام",
    userRole: user?.role || "system",
    type,
    desc,
    targetId,
    page: currentPage,
    device: getDeviceInfo(),
    action: type,
    permissionSchemaVersion: PERMISSIONS_SCHEMA_VERSION,
    auditSchemaVersion: AUDIT_SCHEMA_VERSION,
  };
  const newHistory = [entry, ...history].slice(0, 2000);
  return { ...plan, _history: newHistory };
}

