function getValidStatuses(cat,plan){
  // All statuses are dynamic — base defaults + custom states from plan
  return getAllStatuses(plan).map(s=>s.id);
}
function parseAnalyticsNum(v){
  if(v==null||v==="")return 0;
  const s=String(v).replace(/\s/g,"").replace(/,/g,"");
  if(s==="")return 0;
  const n=Number(s);
  return Number.isFinite(n)?n:0;
}
function formatNum(n){
  const v=parseAnalyticsNum(n);
  if(v===0)return "0";
  if(v>=1000000)return (v/1000000).toFixed(1).replace(/\.0$/,"")+"M";
  if(v>=1000)return (v/1000).toFixed(1).replace(/\.0$/,"")+"K";
  return v.toLocaleString();
}
function getCurrMonthKey(){var n=new Date();return n.getFullYear()+"-"+String(n.getMonth()+1).padStart(2,"0");}
function getPrevMonthKey(){var n=new Date(),y=n.getFullYear(),m=n.getMonth();if(m===0){y--;m=11;}else{m--;}return y+"-"+String(m+1).padStart(2,"0");}
function getMonthLabel(key){if(!key)return"";var p=key.split("-");return(MONTHS_AR[parseInt(p[1],10)-1]||p[1])+" "+p[0];}
function buildMonthAgg(posts){
  var map={};
  for(var i=0;i<posts.length;i++){
    var p=posts[i];
    if(!p.analytics||!p.dateKey)continue;
    var d=new Date(p.dateKey);if(isNaN(d.getTime()))continue;
    var mk=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");
    var aid=p.accountId||"unassigned";
    if(!map[mk])map[mk]={};
    if(!map[mk][aid])map[mk][aid]={views:0,revenue:0,engagement:0,posts:0};
    var m=map[mk][aid];
    m.views+=parseAnalyticsNum(p.analytics.views);
    m.revenue+=parseAnalyticsNum(p.analytics.revenue);
    m.engagement+=parseAnalyticsNum(p.analytics.likes)+parseAnalyticsNum(p.analytics.comments)+parseAnalyticsNum(p.analytics.shares)+parseAnalyticsNum(p.analytics.saves);
    m.posts+=1;
  }
  return map;
}
function calcMoM(md,aid,curr,prev){
  var c=(md[curr]&&md[curr][aid])||{};var p=(md[prev]&&md[prev][aid])||{};
  function one(k){var cv=c[k]||0,pv=p[k]||0,dl=cv-pv,pc=pv>0?(dl/pv)*100:null;return{current:cv,previous:pv,delta:dl,pct:pc};}
  return{views:one("views"),revenue:one("revenue"),engagement:one("engagement"),posts:one("posts")};
}
function calcGoal(goal,val){
  var now=new Date(),day=now.getDate(),dim=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
  var prog=goal.target>0?(val/goal.target)*100:0;
  var exp=(goal.target/dim)*day;
  var pd=val-exp;
  var st="On Track";if(pd<-0.1*goal.target)st="Behind";if(pd>0.1*goal.target)st="Ahead";
  return{prog:Math.min(prog,100),progRaw:prog,rem:Math.max(goal.target-val,0),exp:exp,st:st,eom:day>0?(val/day)*dim:0};
}
