// ══════════════ PLATFORM → CONTENT TYPE INHERITANCE (Phase 2) ══════════════
// Hierarchy: Global defaults → Platform → Content Type → Account override → Post override.
// Phase 1 only establishes the data contract + migration helpers. UI editing is intentionally
// deferred to later phases so we can change one layer at a time without breaking existing posts.
const ACCOUNT_CONFIG_SCHEMA_VERSION = 1;
const CONTENTOS_VERSION = "30.20";
const VERSIONING_SCHEMA_VERSION = 1;
const VERSION_SNAPSHOT_LIMIT = 12;
let VERSION_SNAPSHOT_KEY = "contentos_version_snapshots_v1"; // re-scoped per workspace by ContentOSModule
const RAW_METRIC_SCHEMA_VERSION = 1;
const PLATFORM_ANALYTICS_SCHEMA_VERSION = 1;
const ANALYTICS_HISTORY_SCHEMA_VERSION = 1;
const CANONICAL_METRIC_SCHEMA_VERSION = 1;
const KPI_FORMULA_SCHEMA_VERSION = 1;
const CONTENT_INTELLIGENCE_SCHEMA_VERSION = 1;
const DEFAULT_CANONICAL_METRICS = [
  {id:"cm_views",key:"views",label:"Views / المشاهدات",unit:"count",description:"عدد مرات المشاهدة/التشغيل القابلة للمقارنة عندما تكون دلالتها متقاربة.",active:true},
  {id:"cm_reach",key:"reach",label:"Reach / الوصول",unit:"count",description:"عدد الحسابات/الأشخاص الفريدين الذين وصل إليهم المحتوى، عندما توفر المنصة هذا التعريف.",active:true},
  {id:"cm_likes",key:"likes",label:"Likes / الإعجابات",unit:"count",description:"إعجابات المحتوى.",active:true},
  {id:"cm_comments",key:"comments",label:"Comments / التعليقات",unit:"count",description:"التعليقات على المحتوى.",active:true},
  {id:"cm_shares",key:"shares",label:"Shares / المشاركات",unit:"count",description:"مرات مشاركة المحتوى.",active:true},
  {id:"cm_saves",key:"saves",label:"Saves / الحفظ",unit:"count",description:"مرات حفظ المحتوى عندما توفرها المنصة.",active:true},
  {id:"cm_clicks",key:"clicks",label:"Clicks / النقرات",unit:"count",description:"النقرات المرتبطة بالمحتوى/الرابط حسب تعريف المصدر.",active:true},
  {id:"cm_impressions",key:"impressions",label:"Impressions / مرات الظهور",unit:"count",description:"مرات الظهور حسب تعريف المنصة.",active:true},
  {id:"cm_watch_time",key:"watch_time",label:"Watch Time / وقت المشاهدة",unit:"duration",description:"إجمالي وقت المشاهدة مع الحفاظ على وحدة المصدر.",active:true},
  {id:"cm_revenue",key:"revenue",label:"Revenue / الإيراد",unit:"currency",description:"الإيراد المرتبط بالمحتوى/الفترة.",active:true}
];
function normalizeCanonicalMetrics(raw){
  const list=Array.isArray(raw)?raw:[];
  const byId=new Map(list.filter(Boolean).map(m=>[m.id,m]));
  DEFAULT_CANONICAL_METRICS.forEach(d=>{ if(!byId.has(d.id)) byId.set(d.id,{...d}); else byId.set(d.id,{...d,...byId.get(d.id),id:d.id,key:byId.get(d.id).key||d.key}); });
  return Array.from(byId.values()).map(m=>({...m,active:m.active!==false}));
}
function getCanonicalMetrics(plan){ return normalizeCanonicalMetrics(plan?._canonicalMetrics); }
function getCanonicalMetric(plan,id){ return getCanonicalMetrics(plan).find(m=>m.id===id)||null; }
function ensureCanonicalMetricArchitecture(plan){
  let changed=false;
  const canonical=normalizeCanonicalMetrics(plan?._canonicalMetrics);
  if(JSON.stringify(plan?._canonicalMetrics||[])!==JSON.stringify(canonical)) changed=true;
  const platforms=(plan?._platforms||[]).map(p=>{
    const ac=p.analyticsConfig&&typeof p.analyticsConfig==="object"?p.analyticsConfig:{};
    const metrics=Array.isArray(ac.platformMetrics)?ac.platformMetrics.map(m=>({...m})):[];
    const mappings={...(ac.metricMappings||{})};
    metrics.forEach(m=>{ if(m.canonicalMetricId && !mappings[m.id]) mappings[m.id]=m.canonicalMetricId; });
    const nextAc={...emptyPlatformAnalyticsConfig(p),...ac,platformMetrics:metrics,metricMappings:mappings,schemaVersion:PLATFORM_ANALYTICS_SCHEMA_VERSION};
    if(JSON.stringify(ac)!==JSON.stringify(nextAc)) changed=true;
    return {...p,analyticsConfig:nextAc};
  });
  return changed?{...plan,_canonicalMetrics:canonical,_platforms:platforms,_canonicalMetricSchemaVersion:CANONICAL_METRIC_SCHEMA_VERSION}:plan;
}
function resolveCanonicalMetricId(plan,platformId,metricId){
  const m=getCanonicalMetric(plan,metricId); if(m) return m.id;
  const p=getEffectivePlatformAnalytics(plan,platformId);
  const pm=(p.platformMetrics||[]).find(x=>x.id===metricId);
  return pm?.canonicalMetricId || p.metricMappings?.[metricId] || null;
}
function getCanonicalMetricMappings(plan,platformId){
  const p=getEffectivePlatformAnalytics(plan,platformId); const out={...(p.metricMappings||{})};
  (p.platformMetrics||[]).forEach(m=>{ if(m.canonicalMetricId) out[m.id]=m.canonicalMetricId; });
  return out;
}
const ACCOUNT_DASHBOARD_SCHEMA_VERSION = 1;
const ACCOUNT_DASHBOARD_DEFAULT = {
  mode: "inherit", enabled: true, defaultTab: "entry",
  tabs: ["entry","format","platform","system","layers","intelligence"],
  cards: ["measurements","views","reach","interactions","performance"]
};
function normalizeAccountDashboard(raw){
  const r=raw&&typeof raw==="object"?raw:{};
  return {...ACCOUNT_DASHBOARD_DEFAULT,...r,mode:r.mode||"inherit",schemaVersion:ACCOUNT_DASHBOARD_SCHEMA_VERSION,
    tabs:Array.isArray(r.tabs)?r.tabs.filter(Boolean):ACCOUNT_DASHBOARD_DEFAULT.tabs.slice(),
    cards:Array.isArray(r.cards)?r.cards.filter(Boolean):ACCOUNT_DASHBOARD_DEFAULT.cards.slice()};
}

function emptyPlatformAnalyticsConfig(platform){
  const p=platform||{};
  return {
    schemaVersion: PLATFORM_ANALYTICS_SCHEMA_VERSION,
    enabled: true,
    source: "manual",
    platformMetrics: [],
    metricMappings: {},
    pageKpis: Array.isArray(p.pageKpis)?p.pageKpis.map(k=>({...k,inputs:Array.isArray(k.inputs)?k.inputs.map(i=>({...i})):[]})):[],
  };
}
function ensurePlatformAnalyticsArchitecture(plan){
  let changed=false;
  const platforms=(plan?._platforms||[]).map(p=>{
    const current=p.analyticsConfig&&typeof p.analyticsConfig==="object"?p.analyticsConfig:{};
    const base=emptyPlatformAnalyticsConfig(p);
    const next={...base,...current,schemaVersion:PLATFORM_ANALYTICS_SCHEMA_VERSION,
      platformMetrics:Array.isArray(current.platformMetrics)?current.platformMetrics.map(m=>({...m})):[],
      metricMappings:{...(current.metricMappings||{})},
      pageKpis:Array.isArray(current.pageKpis)?current.pageKpis.map(k=>({...k,inputs:Array.isArray(k.inputs)?k.inputs.map(i=>({...i})):[]})):base.pageKpis};
    // Preserve the existing platform-level page KPI source of truth while giving it an explicit analytics layer.
    if(!Array.isArray(current.pageKpis) && Array.isArray(p.pageKpis)){ changed=true; }
    if(JSON.stringify(p.analyticsConfig||{})!==JSON.stringify(next)) changed=true;
    return {...p,analyticsConfig:next};
  });
  return changed?{...plan,_platforms:platforms,_platformAnalyticsSchemaVersion:PLATFORM_ANALYTICS_SCHEMA_VERSION}:plan;
}
function getEffectivePlatformAnalytics(plan,platformId){
  const p=getPlatforms(plan).find(x=>x.id===platformId);
  if(!p) return emptyPlatformAnalyticsConfig(null);
  return {...emptyPlatformAnalyticsConfig(p),...(p.analyticsConfig||{}),
    platformMetrics:Array.isArray(p.analyticsConfig?.platformMetrics)?p.analyticsConfig.platformMetrics:[],
    metricMappings:{...(p.analyticsConfig?.metricMappings||{})},
    pageKpis:Array.isArray(p.analyticsConfig?.pageKpis)?p.analyticsConfig.pageKpis:(p.pageKpis||[])};
}

function emptyAccountContentConfig(){
  return {
    schemaVersion: ACCOUNT_CONFIG_SCHEMA_VERSION,
    mode: "inherit",
    stages: null,
    taskOverrides: {},
    fieldOverrides: {},
    kpiMode: "inherit",
    postKpis: null,
    minInputs: null,
    rawMetrics: null,
    analytics: null,
  };
}

function ensureAccountConfig(account){
  const a = account || {};
  const current = a.contentConfig && typeof a.contentConfig === "object" ? a.contentConfig : {};
  const normalized = {};
  Object.keys(current).forEach(pid=>{
    const byType = current[pid] && typeof current[pid] === "object" ? current[pid] : {};
    normalized[pid] = {};
    Object.keys(byType).forEach(ctId=>{
      const existing = byType[ctId]||{};
      normalized[pid][ctId] = {
        ...emptyAccountContentConfig(),
        ...existing,
        schemaVersion: ACCOUNT_CONFIG_SCHEMA_VERSION,
        // Backward compatibility: older account configs used `mode` for the shared
        // customization layer. If they already contained KPI data, preserve it as a KPI override.
        kpiMode: existing.kpiMode || (Array.isArray(existing.postKpis) ? "custom" : "inherit"),
        taskOverrides: {...(existing.taskOverrides||{})},
        fieldOverrides: {...(existing.fieldOverrides||{})},
      };
    });
  });
  return {...a, contentConfig: normalized, dashboard: normalizeAccountDashboard(a.dashboard), configSchemaVersion: ACCOUNT_CONFIG_SCHEMA_VERSION};
}

function getEffectiveAccountDashboard(plan,account){
  const d=normalizeAccountDashboard(account?.dashboard);
  if(d.mode!=="custom") return {...ACCOUNT_DASHBOARD_DEFAULT,mode:"inherit",schemaVersion:ACCOUNT_DASHBOARD_SCHEMA_VERSION};
  return d;
}

function getAccountContentConfig(account,platformId,contentTypeId){
  const cfg = account?.contentConfig?.[platformId]?.[contentTypeId];
  return cfg ? {...emptyAccountContentConfig(),...cfg} : emptyAccountContentConfig();
}

function getEffectiveAccountAnalytics(plan,account,platformId,contentTypeId){
  const ct=getFormatById(plan,platformId,contentTypeId);
  const cfg=getAccountContentConfig(account,platformId,contentTypeId);
  const platform=getEffectivePlatformAnalytics(plan,platformId);
  const a=cfg.analytics&&typeof cfg.analytics==="object"?cfg.analytics:{};
  const platformMetrics=Array.isArray(platform.platformMetrics)?platform.platformMetrics:[];
  const kpis=Array.isArray(ct?.postKpis)?ct.postKpis:[];
  const selectedMetricIds=Array.isArray(a.metricIds)?a.metricIds:null;
  const selectedKpiIds=Array.isArray(a.kpiIds)?a.kpiIds:null;
  return {
    mode:a.mode||"inherit",
    enabled:a.mode==="custom" && typeof a.enabled==="boolean" ? a.enabled : platform.enabled!==false,
    source:a.mode==="custom" && a.source ? a.source : (platform.source||"manual"),
    metricIds:selectedMetricIds,
    kpiIds:selectedKpiIds,
    platformMetrics:selectedMetricIds?platformMetrics.filter(m=>selectedMetricIds.includes(m.id)):platformMetrics,
    kpis:selectedKpiIds?kpis.filter(k=>selectedKpiIds.includes(k.id)):kpis,
    inheritedPlatformAnalytics:platform
  };
}

function getEffectiveContentConfig(plan,account,platformId,contentTypeId){
  const ct = getFormatById(plan,platformId,contentTypeId);
  const accountCfg = getAccountContentConfig(account,platformId,contentTypeId);
  return {
    source: accountCfg.mode === "custom" ? "account" : "platform",
    stages: accountCfg.mode === "custom" && Array.isArray(accountCfg.stages) ? accountCfg.stages : (ct?.stages||[]),
    postKpis: accountCfg.kpiMode === "custom" && Array.isArray(accountCfg.postKpis) ? accountCfg.postKpis : (ct?.postKpis||[]),
    minInputs: accountCfg.kpiMode === "custom" && Array.isArray(accountCfg.minInputs) ? accountCfg.minInputs : (ct?.minInputs||[]),
    taskOverrides: accountCfg.taskOverrides||{},
    fieldOverrides: accountCfg.fieldOverrides||{},
    rawMetrics: accountCfg.rawMetrics || (ct?.rawMetrics||[]),
    analytics: getEffectiveAccountAnalytics(plan,account,platformId,contentTypeId),
  };
}


function metricKeyLabel(v){ return String(v||"").trim().toLowerCase().replace(/[\s_\-]+/g," "); }
function makeRawMetricId(ctId,label){
  const slug=String(label||"metric").trim().toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]+/g,"_").replace(/^_|_$/g,"").slice(0,48)||"metric";
  return "rm_"+String(ctId||"ct").replace(/[^a-zA-Z0-9_]/g,"_")+"_"+slug;
}
function ensureRawMetricArchitecture(plan){
  let changed=false;
  const platforms=(plan?._platforms||[]).map(pl=>({...pl,contentTypes:(pl.contentTypes||[]).map(ct=>{
    const existing=Array.isArray(ct.rawMetrics)?ct.rawMetrics.map(m=>({...m})):[];
    const byLabel=new Map(existing.map(m=>[metricKeyLabel(m.label||m.name),m]));
    let metrics=existing;
    const kpis=(ct.postKpis||[]).map(k=>({...k,inputs:Array.isArray(k.inputs)?k.inputs.map(inp=>{
      let metric=inp.metricId?byLabel.get(metricKeyLabel(inp.label)):null;
      if(!metric) metric=byLabel.get(metricKeyLabel(inp.label));
      if(!metric){
        metric={id:inp.metricId||makeRawMetricId(ct.id,inp.label),label:inp.label||"Metric",type:"number",unit:"",source:"platform",active:true};
        byLabel.set(metricKeyLabel(metric.label),metric); metrics=[...metrics,metric]; changed=true;
      }
      if(inp.metricId!==metric.id){ changed=true; return {...inp,metricId:metric.id}; }
      return inp;
    }):[],calc:k.calc?{...k.calc}:k.calc}));
    if(JSON.stringify(kpis)!==JSON.stringify(ct.postKpis||[]) || JSON.stringify(metrics)!==JSON.stringify(ct.rawMetrics||[])) changed=true;
    return {...ct,rawMetricSchemaVersion:RAW_METRIC_SCHEMA_VERSION,rawMetrics:metrics,postKpis:kpis};
  })}));
  return changed?{...plan,_platforms:platforms,_rawMetricSchemaVersion:RAW_METRIC_SCHEMA_VERSION}:plan;
}

function migrateAccountConfigs(plan){
  const accounts = Array.isArray(plan?._accounts) ? plan._accounts : [];
  let changed = false;
  const normalized = accounts.map(acc=>{
    const next = ensureAccountConfig(acc);
    if(next.configSchemaVersion !== acc.configSchemaVersion || !acc.contentConfig) changed = true;
    return next;
  });
  return changed ? {...plan,_accounts:normalized,_accountConfigSchemaVersion:ACCOUNT_CONFIG_SCHEMA_VERSION} : plan;
}

function ensureKpiFormulaArchitecture(plan){
  let changed=false;
  const platforms=(plan?._platforms||[]).map(pl=>({...pl,contentTypes:(pl.contentTypes||[]).map(ct=>{
    const kpis=(ct.postKpis||[]).map(k=>{
      const calc=k.calc&&typeof k.calc==="object"?{...k.calc}:{type:"manual"};
      const type=calc.type||"manual";
      const next={...k,formulaSchemaVersion:KPI_FORMULA_SCHEMA_VERSION,calc:{...calc,type}};
      if(next.calc.type==="subtract") next.calc.type="difference";
      if(JSON.stringify(next)!==JSON.stringify(k)) changed=true;
      return next;
    });
    return {...ct,postKpis:kpis,kpiFormulaSchemaVersion:KPI_FORMULA_SCHEMA_VERSION};
  })}));
  const accounts=(plan?._accounts||[]).map(acc=>{
    const contentConfig={...(acc.contentConfig||{})};
    Object.keys(contentConfig).forEach(pid=>{
      const byType={...(contentConfig[pid]||{})};
      Object.keys(byType).forEach(ctId=>{
        const cfg=byType[ctId];
        if(!cfg||!Array.isArray(cfg.postKpis))return;
        const nextPostKpis=cfg.postKpis.map(k=>{const calc=k.calc&&typeof k.calc==="object"?{...k.calc}:{type:"manual"}; return {...k,formulaSchemaVersion:KPI_FORMULA_SCHEMA_VERSION,calc:{...calc,type:calc.type||"manual"}};});
        if(JSON.stringify(nextPostKpis)!==JSON.stringify(cfg.postKpis)) changed=true;
        byType[ctId]={...cfg,postKpis:nextPostKpis};
      });
      contentConfig[pid]=byType;
    });
    return {...acc,contentConfig};
  });
  return changed?{...plan,_platforms:platforms,_accounts:accounts,_kpiFormulaSchemaVersion:KPI_FORMULA_SCHEMA_VERSION}:plan;
}

// Materializes the seeded default platforms / layers into the actual plan data
// (instead of only being a JS fallback) the first time a fresh plan is loaded,
// so they show up as real, editable records in "إدارة المنصات" و"الطبقات" right away.
function ensureDefaults(plan){
  let p = plan;
  if(!p._platforms || p._platforms.length===0){
    const ct = {...(p._contentTypes||{})};
    DEFAULT_PLATFORMS.forEach(plt=>{ ct[plt.id] = plt.contentTypes||[]; });
    p = {...p, _platforms: DEFAULT_PLATFORMS.map(x=>({...x})), _contentTypes: ct};
  }
  if(!p._layerGroups || p._layerGroups.length===0){
    p = {...p, _layerGroups: DEFAULT_LAYER_GROUPS.map(x=>({...x}))};
  }
  if(!p._layers || p._layers.length===0){
    p = {...p, _layers: DEFAULT_LAYERS.map(x=>({...x}))};
  }
  // Phase 1 migration: every account now has an isolated override container.
  // Empty containers mean "inherit" and therefore do not duplicate platform defaults.
  p = migrateAccountConfigs(p);
  p = ensureRawMetricArchitecture(p);
  p = ensurePlatformAnalyticsArchitecture(p);
  p = ensureCanonicalMetricArchitecture(p);
  p = ensureKpiFormulaArchitecture(p);
  p = normalizeAnalyticsHistory(p);
  // Phase 18: normalize permission/audit metadata without changing existing role defaults.
  const users=(p._users||[]).map(u=>({...u,permissions:{...(u.permissions||{}),actions:{...((u.permissions&&u.permissions.actions)||{})}}}));
  p={...p,_users:users,_permissionsSchemaVersion:PERMISSIONS_SCHEMA_VERSION,_auditSchemaVersion:AUDIT_SCHEMA_VERSION,_history:Array.isArray(p._history)?p._history:[]};
  const v=p._versioning&&typeof p._versioning==="object"?p._versioning:{};
  p={...p,_versioning:{schemaVersion:VERSIONING_SCHEMA_VERSION,currentVersion:v.currentVersion||CONTENTOS_VERSION,lastMigrationAt:v.lastMigrationAt||new Date().toISOString(),lastSnapshotAt:v.lastSnapshotAt||null}};
  return p;
}

